(()=>{
const sheet=new CSSStyleSheet();sheet.replaceSync("/* Original Nightwave adaptation of the day/night interaction reference. */\n:host{--control-switch-thickness:44px!important;--control-switch-min-touch-size:44px!important;--nw-toggle-width:112px;max-width:var(--nw-toggle-width);margin-left:auto;--control-switch-border-radius:24px!important}\n.switch{padding:4px;border:1px solid #bc8bee66;box-shadow:inset 3px 4px 8px #0c0327bb,inset 0 -1px 1px #cb9cef44;isolation:isolate}\n.switch .background{opacity:1!important;overflow:hidden;background:radial-gradient(circle at 56% 21%,#eee0ff 0 1px,transparent 1.4px),radial-gradient(circle at 81% 30%,#b6a5f1 0 1px,transparent 1.5px),radial-gradient(circle at 68% 77%,#e2d8ff 0 .8px,transparent 1.3px),radial-gradient(circle at 91% 67%,#bcece8 0 1px,transparent 1.4px),linear-gradient(135deg,#170d2d,#463067)!important;box-shadow:inset 3px 3px 7px #0b031c99}\n.background:before{content:\"\";position:absolute;inset:0;background:radial-gradient(circle at 80% 50%,#3e939a66,transparent 65%),linear-gradient(120deg,#304369,#215e69);clip-path:circle(0% at 17% 50%);transition:clip-path .65s cubic-bezier(.4,0,.2,1)}\n.background:after{content:\"\";position:absolute;left:-14px;right:-30px;bottom:-2px;height:20px;background:radial-gradient(ellipse 17px 9px at 17px 17px,#a6e1df66 97%,transparent),radial-gradient(ellipse 13px 11px at 35px 15px,#a6e1df66 97%,transparent),radial-gradient(ellipse 22px 8px at 56px 18px,#a6e1df66 97%,transparent),radial-gradient(ellipse 15px 9px at 104px 19px,#a6e1df33 97%,transparent);opacity:0;transform:translateX(18px) translateY(12px);transition:opacity .45s,transform .65s cubic-bezier(.2,.7,.3,1);pointer-events:none}\n.switch:after{content:\"OFF\";position:absolute;right:17px;top:17px;color:#d3bfe8;font:600 10px/1 var(--ha-font-family-body);letter-spacing:1px;pointer-events:none;z-index:1;text-shadow:0 1px 3px #140b27}\n.switch .button{position:absolute;left:4px;top:4px;width:34px!important;height:34px!important;border-radius:50%!important;background:radial-gradient(circle at 30% 22%,#f2eaff,#b6a5d0 58%,#7d699d)!important;box-shadow:0 3px 5px #090216aa,inset 0 1px 2px #fffc,inset 0 -2px 3px #51436c88;transition:transform .6s cubic-bezier(.34,1.4,.48,1),box-shadow .4s,scale .15s!important;transform:translateX(0) rotate(-15deg)!important;z-index:2}\n.button ha-svg-icon{display:none}\n.button:before{content:\"\";position:absolute;inset:0;border:0;border-radius:50%;background:radial-gradient(circle 4px at 32% 39%,#84729e80 95%,transparent),radial-gradient(circle 2px at 66% 30%,#8d7aa666 95%,transparent),radial-gradient(circle 3px at 60% 69%,#84729e70 95%,transparent);opacity:1;transition:opacity .35s}\n.button:after{content:\"\";position:absolute;inset:-5px;border:1px solid #b9fff04d;border-radius:50%;box-shadow:0 0 0 5px #96fce511;opacity:0;transform:scale(.6);transition:opacity .45s,transform .6s}\n.switch[checked] .background:before{clip-path:circle(125% at 83% 50%)}\n.switch[checked] .background:after{opacity:1;transform:translateX(0) translateY(0)}\n.switch[checked]:after{content:\"ON\";right:auto;left:19px;color:#e1fff5}\n.switch[checked] .button{transform:translateX(68px) rotate(15deg)!important;background:radial-gradient(circle at 32% 24%,#f0fff7,#87f2da 55%,#36aaa8)!important;box-shadow:0 3px 5px #07152aaa,0 0 13px #35f1d255,inset 0 1px 2px #fff,inset 0 -2px 3px #258d9988}\n.switch[checked] .button:before{opacity:0}\n.switch[checked] .button:after{opacity:1;transform:scale(1)}\n@media(hover:hover) and (pointer:fine){.switch:not([disabled]):hover{border-color:#d0aff0aa}.switch:not([disabled]):hover .button{scale:1.04}}\n.switch:not([disabled]):active .button{scale:.94}\n.switch:not([disabled]):focus-visible{outline:2px solid #a4ffe9;outline-offset:3px}\n@media(prefers-reduced-motion:reduce){.switch .button,.background:before,.background:after,.button:before,.button:after{transition:none!important}.switch:not([disabled]):hover .button,.switch:not([disabled]):active .button{scale:1}}\n");
customElements.whenDefined('ha-control-switch').then(()=>{
 const proto=customElements.get('ha-control-switch').prototype,old=proto.updated;
 function decorate(e){if(!e.shadowRoot)return;let host=e,inside=false;while(host){if(host.localName==='hui-root'){inside=true;break;}host=host.parentElement||host.getRootNode()?.host;}
 const sheets=e.shadowRoot.adoptedStyleSheets.filter(s=>s!==sheet);
 e.shadowRoot.adoptedStyleSheets=nw.active()&&inside?[...sheets,sheet]:sheets;}
 proto.updated=function(...args){const result=old?.apply(this,args);decorate(this);return result;};
 const scan=r=>{for(const e of r.querySelectorAll('*')){if(e.localName==='ha-control-switch')decorate(e);if(e.shadowRoot)scan(e.shadowRoot);}};scan(document);
});})();

// Compact entity-row switches, distinct from the large sky toggles.
nwDecorate('ha-switch', "\n.switch{background:linear-gradient(180deg,#1d0d30,#432454)!important;box-shadow:inset 2px 3px 5px #0c031a99,inset 0 -1px 1px #cf9df433;border:1px solid #a37dc244!important;transition:background .2s,box-shadow .2s}\n.checked .switch{background:linear-gradient(110deg,#60429e,#17606a 70%,#217c73)!important;box-shadow:inset 2px 2px 4px #071c3466,0 0 8px #35f1d219;border-color:#52ccb277!important}\n.thumb{background:linear-gradient(145deg,#efe3ff,#aa87cd)!important;box-shadow:0 2px 5px #0c031a99,inset 0 1px 1px #ffffffaa;transition:translate .18s,box-shadow .18s}\n.checked .thumb{background:linear-gradient(145deg,#e5fff8,#69dec9)!important;box-shadow:0 2px 5px #031b2299,0 0 5px #62eac866}\nlabel:focus-within .switch{outline:2px solid #8cffe9;outline-offset:3px}\nlabel:active .thumb{box-shadow:inset 1px 2px 3px #73558766}\n@media(prefers-reduced-motion:reduce){.switch,.thumb{transition:none!important}}\n");
